import type { IconType } from 'react-icons';

/**
 * Bespoke per-port-type glyphs — cloned pixel-for-pixel from the real Rack
 * Device Editor's own SVGs (every id/viewBox/path/polygon/rect value below
 * was copied verbatim out of a real pasted toolbar-chip + placed-port DOM
 * dump, not invented). Replaces the earlier react-icons stand-ins
 * (TbPlugConnected etc.), which never matched the real connector
 * silhouettes.
 *
 * The real editor also mirrors the Copper glyph between a port's row 0 and
 * row 1 — two vertically stacked ports face each other — and PS/2's
 * viewBox/path is reused for the toolbar chip only (placed ports weren't
 * observed for every type). Both are cosmetic details, simplified here to
 * one consistent orientation everywhere; the data model doesn't distinguish
 * "which way a jack icon points".
 *
 * Typed as react-icons' `IconType` (not implemented via react-icons) purely
 * so these drop straight into `PortTypeDef.icon` and the existing
 * `def?.icon || TbTypography` fallback in DeviceFaceGrid.tsx without
 * touching either call site — IconBaseProps is a strict superset of the
 * `{ className }` these actually receive.
 */

export const CopperIcon: IconType = (props) => (
  <svg viewBox="0 0 11 9" aria-hidden="true" {...props}>
    <polygon points="11 9 11 2 7.7 2 7.7 0 3.3 0 3.3 2 0 2 0 9" fill="currentColor" />
  </svg>
);

